  }

  /** Enqueue a durable job for async processing */
  async enqueueJob(client: pg.PoolClient, merchantId: string, customerId: string, erasureRequestId: string): Promise<void> {
    await client.query(
      `INSERT INTO operations.jobs(queue, job_type, merchant_id, payload, max_attempts)
       VALUES('erasures', 'customer_erasure', $1, $2, 8)`,
      [merchantId, JSON.stringify({ customerId, merchantId, erasureRequestId })],
    );
  }

  /** Claim a pending erasure job */
  async claimJob(client: pg.PoolClient, workerId: string): Promise<ErasureJob | undefined> {
    const result = await client.query(
      `UPDATE operations.jobs
       SET status = 'processing', attempts = attempts + 1, locked_by = $1, locked_at = now(),
           lease_expires_at = now() + interval '120 seconds', last_error = NULL
       WHERE id = (
         SELECT id FROM operations.jobs
         WHERE queue = 'erasures' AND status IN ('pending', 'retry') AND available_at <= now()
         ORDER BY available_at, created_at
         FOR UPDATE SKIP LOCKED LIMIT 1
       )
       RETURNING id, merchant_id, job_type, payload, attempts, status`,
      [workerId],
    );
    const job = result.rows[0] as (ErasureJob & { payload: string }) | undefined;
    if (!job) return undefined;
    return { ...job, payload: JSON.parse(job.payload) };
  }

  async completeJob(client: pg.PoolClient, jobId: string): Promise<void> {
    await client.query(
      `UPDATE operations.jobs
       SET status = 'completed', locked_by = NULL, locked_at = NULL, lease_expires_at = NULL
       WHERE id = $1`,
      [jobId],
    );
  }

  async failJob(client: pg.PoolClient, jobId: string, error: string, attempts: number, maxAttempts: number): Promise<void> {
    const delay = Math.min(300, 2 ** Math.max(0, attempts));
    if (attempts >= maxAttempts) {
      await client.query(
        `WITH failed AS (
           UPDATE operations.jobs
           SET status = 'dead', locked_by = NULL, locked_at = NULL, lease_expires_at = NULL, last_error = $2
           WHERE id = $1 RETURNING *
         )
         INSERT INTO operations.dead_letters(source, source_id, event_type, payload, error)
         SELECT 'job', id::text, job_type, payload, $2 FROM failed`,
        [jobId, error],
      );
      return;
    }
    await client.query(
      `UPDATE operations.jobs
       SET status = 'retry', available_at = now() + ($2 || ' seconds')::interval,
           locked_by = NULL, locked_at = NULL, lease_expires_at = NULL, last_error = $3
       WHERE id = $1`,
      [jobId, delay, error],
    );
  }

