import type { PoolClient } from 'pg';
import { config } from '../../../packages/config/src/index.js';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, ensureBucket, objectStore } from '../../../packages/storage/src/minio.js';
import { ErasureRepository, type ErasureRequestRow } from './erasure-repository.js';

export interface ErasureResult {
  status: number;
  body: Record<string, unknown>;
}

export class ErasureService {
  private readonly repository = new ErasureRepository();

  constructor(private readonly redis = new Redis(config().REDIS_URL)) {}

  /** Create an erasure request or return the existing one */
  async createErasureRequest(merchantId: string, customerId: string): Promise<ErasureResult> {
    const existing = await this.repository.findByCustomer(merchantId, customerId);
    if (existing) {
      return { status: 202, body: this.toResponse(existing) };
    }

    const row = await this.repository.create(merchantId, customerId);

    await transaction(async (client) => {
      await this.repository.enqueueJob(client, merchantId, customerId, row.id);
    });

    return { status: 202, body: this.toResponse(row) };
  }

  /** Get an erasure request by ID */
  async getErasureRequest(merchantId: string, requestId: string): Promise<ErasureResult | undefined> {
    const row = await this.repository.findById(merchantId, requestId);
    if (!row) return undefined;
    return { status: 200, body: this.toResponse(row) };
  }

  /** Process a single erasure job */
  async processJob(
    client: PoolClient,
    job: { id: string; merchant_id: string; customer_id: string; attempts: number; payload: { customerId: string; merchantId: string; erasureRequestId: string } },
  ): Promise<void> {
    const { customerId, erasureRequestId } = job.payload;
    const merchantId = job.merchant_id;

    try {
      await this.repository.incrementAttempts(client, erasureRequestId);

      // Step 1: Delete PII from core customer tables
      await this.repository.anonymizeCustomerRecord(client, customerId);
      await this.repository.deleteAddresses(client, customerId);
      await this.repository.deleteContacts(client, customerId);
      await this.repository.deletePaymentMethods(client, customerId);
      await this.repository.deleteSupportMessages(client, customerId);

      // Step 2: Delete PII from provider sandbox
      await this.repository.redactProviderCustomer(client, customerId);

      // Step 3: Delete notification preferences
      await this.repository.deleteNotificationPreferences(client, customerId);

      // Step 4: Purge Redis cache
      const redisKeys = await this.repository.getRedisKeysToPurge(merchantId, customerId);
      for (const key of redisKeys) {
        try { await this.redis.del(key); } catch { /* best-effort */ }
      }

      // Step 5: Delete from OpenSearch
      const osId = await this.repository.getOpenSearchId(merchantId, customerId);
      try {
        await searchClient.delete({ index: CUSTOMER_INDEX, id: osId, refresh: false });
      } catch (err) {
        const e = err as { statusCode?: number };
        if (e.statusCode !== 404) throw err;
      }

      // Step 6: Delete documents from MinIO
      const manifests = await this.repository.getCustomerDocumentManifests(customerId);
      await ensureBucket();
      for (const { object_key } of manifests) {
        try { await objectStore.removeObject(DOCUMENT_BUCKET, object_key); } catch { /* best-effort */ }
      }

      // Step 7: Mark as completed
      await this.repository.updateStatus(client, erasureRequestId, 'completed');
      await this.repository.completeJob(client, job.id);

      logger.info({ customerId, erasureRequestId }, 'erasure completed');
    } catch (error) {
      const message = error instanceof Error ? error.message.slice(0, 300) : String(error).slice(0, 300);
      await this.repository.updateStatus(client, erasureRequestId, 'failed', message);
      await this.repository.failJob(client, job.id, message, job.attempts, 8);
      throw error;
    }
  }

  /** Start the erasure job worker loop */
  async startWorker(signal: AbortSignal): Promise<void> {
    const workerId = `customer-service-erasures-${Math.random().toString(36).slice(2)}`;
    logger.info({ workerId }, 'erasure worker started');

    while (!signal.aborted) {
      try {
        // Recover expired leases
        await pool.query(
          `UPDATE operations.jobs
           SET status = 'retry', available_at = now(), locked_by = NULL, locked_at = NULL, lease_expires_at = NULL,
               last_error = COALESCE(last_error, 'worker_lease_expired')
           WHERE queue = 'erasures' AND status = 'processing' AND lease_expires_at < now()`,
        );

        const claimed = await transaction(async (client) => {
          const job = await this.repository.claimJob(client, workerId);
          if (!job) return undefined;

          const attemptResult = await client.query<{ id: string }>(
            `INSERT INTO operations.job_attempts(job_id, worker_id, status, started_at)
             VALUES($1, $2, 'processing', now()) RETURNING id`,
            [job.id, workerId],
          );

          await this.processJob(client, {
            ...job,
            attempts: job.attempts,
            customer_id: job.payload.customerId,
          });

          return job;
        });

        if (!claimed) {
          await new Promise((resolve) => setTimeout(resolve, 250));
        }
      } catch (error) {
        logger.error({ error }, 'erasure worker cycle failed');
        await new Promise((resolve) => setTimeout(resolve, 250));
      }
    }

    await this.redis.quit();
    logger.info('erasure worker stopped');
  }

  private toResponse(row: ErasureRequestRow): Record<string, unknown> {
    return {
      id: row.id,
      customerId: row.customer_id,
      status: row.status,
      attempts: row.attempts,
      createdAt: row.created_at.toISOString(),
      updatedAt: row.updated_at.toISOString(),
      completedAt: row.completed_at?.toISOString() ?? null,
      lastError: row.last_error,
    };
  }
}"}

